export class SessionRegistry {
  private repository: SessionRepository = new NetworkSessionRepository()

  chooseRepository(online: boolean): void {
    if (online) {
      this.repository = new NetworkSessionRepository()
    } else {
      this.repository = new LocalSessionRepository()
    }
  }
}

sources.src/stores/SessionSyncStore.ets:
export class SessionSyncStore {
  @State sessions: SessionRecord[] = []
  private repository: SessionRepository

  async syncSessions(): Promise<void> {
    const loaded = await this.repository.loadSessions()
    this.sessions = loaded
  }
}

